<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject;

use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFail;
use Civi\Lughauth\Features\Access\TrustedClient\Domain\TrustedClientSubjectTypeOptions;

class TrustedClientSubjectTypeVO
{
    public static function fromString(string $value): TrustedClientSubjectTypeVO
    {
        $errorsList = new ConstraintFailList();
        $candidate = self::tryFrom($value, $errorsList);
        if ($errorsList->hasErrors()) {
            throw $errorsList->asConstraintException();
        }
        \assert($candidate instanceof TrustedClientSubjectTypeVO);
        return $candidate;
    }
    public static function from(TrustedClientSubjectTypeVO|TrustedClientSubjectTypeOptions $value): TrustedClientSubjectTypeVO
    {
        return self::fromUnsafe($value);
    }
    public static function tryFrom(mixed $value, ConstraintFailList $list): ?TrustedClientSubjectTypeVO
    {
        if ($value instanceof TrustedClientSubjectTypeVO) {
            // If is a ValueObject, its already validated... nothing to append
            return $value;
        } elseif (is_string($value)) {
            if ($typed = self::readFromString($value)) {
                return self::tryFrom($typed, $list);
            } else {
                $list->add(new ConstraintFail('wrong_format', ['subjectType'], [$value], ['TrustedClientSubjectTypeOptions']));
                return null;
            }
        } elseif (is_a($value, TrustedClientSubjectTypeOptions::class)) {
            return new TrustedClientSubjectTypeVO($value);
        } else {
            $list->add(new ConstraintFail('wrong_type', ['subjectType'], [$value], ['TrustedClientSubjectTypeOptions']));
            return null;
        }
    }
    private static function readFromString(string $enumString): ?TrustedClientSubjectTypeOptions
    {
        if (in_array($enumString, ['pUBLIC', 'public', 'PUBLIC'])) {
            return TrustedClientSubjectTypeOptions::PUBLIC;
        }
        if (in_array($enumString, ['pairwise', 'pAIRWISE', 'PAIRWISE'])) {
            return TrustedClientSubjectTypeOptions::PAIRWISE;
        }
        return null;
    }
    private static function fromUnsafe(mixed $value): TrustedClientSubjectTypeVO
    {
        if ($value instanceof TrustedClientSubjectTypeVO) {
            // If is a ValueObject, its already validated
            return $value;
        } else {
            // If is not a ValueObject, validation is need and exception throw
            $errorsList = new ConstraintFailList();
            $candidate = self::tryFrom($value, $errorsList);
            if ($errorsList->hasErrors()) {
                throw $errorsList->asConstraintException();
            }
            \assert($candidate instanceof TrustedClientSubjectTypeVO);
            return $candidate;
        }
    }
    /**
     * private constructor to avoid build a value without all the rule validations.
     */
    private function __construct(
        private readonly TrustedClientSubjectTypeOptions $subjectType
    ) {
    }
    public function value(): TrustedClientSubjectTypeOptions
    {
        return $this->subjectType;
    }
    public function equals(?TrustedClientSubjectTypeVO $other): bool
    {
        return $this->value() == $other?->value();
    }
}
